import json, re

def last_number(s):
    nums = re.findall(r'-?\d[\d,]*\.?\d*', s)
    if not nums: return None
    return nums[-1].replace(',','')

for step in [0,10,20,30,40,50,60]:
    path=f'results/run60/val_generations/{step}.jsonl'
    n=0; correct=0; score_field=0; disagree=0; nonnum=0; examples=[]
    for line in open(path):
        r=json.loads(line)
        out=r['output']; gt=r['gts']
        ln=last_number(out)
        ok=False
        if ln is not None:
            try: ok = float(ln)==float(gt)
            except: ok=False
        else: nonnum+=1
        n+=1; correct+=ok; score_field+= (r.get('score',0)==1.0 or r.get('acc',0)==1.0)
        if ok != (r.get('score',0)==1.0):
            disagree+=1
            if len(examples)<3: examples.append((gt, ln, out[-80:], r.get('score')))
    print(step, 'n',n,'grader',round(correct/n,4),'logged_score',round(score_field/n,4),'disagree',disagree,'nonnum',nonnum)
    for e in examples: print('   ', e)
EOF

