import pandas as pd
te=pd.read_parquet('raw/gsm8k/main/test-00000-of-00001.parquet')
INSTR='Let\'s think step by step and output the final answer after "####".'
def extract(a):
    m=re.search(r"#### (\-?[0-9\.\,]+)", a); return m.group(1).replace(',','')
rows=[json.loads(l) for l in open('results/run60/val_generations/0.jsonl')]
print('rows',len(rows),'raw',len(te))
bad_q=bad_g=0; examples=[]
