    expected = q + ' ' + INSTR
    if expected not in r['input']:
        bad_q+=1
        if len(examples)<2: examples.append(('Q',i,repr(r['input'][:200]),repr(expected[:200])))
    if r['gts']!=extract(a):
        bad_g+=1
        if len(examples)<2: examples.append(('G',i,r['gts'],extract(a)))
print('bad question/prompt',bad_q,'bad gold',bad_g)
for e in examples: print(e)
EOF

