import json,re,collections
def lastnum_grader(s):
    m=re.findall(r'-?\d[\d,]*\.?\d*', s)
    return m[-1].replace(',','') if m else None
def rew_flex(s,gt):
    import sys; sys.path.insert(0,'.')
    from verl.utils.reward_score import gsm8k
    return gsm8k.compute_score(s,gt,method='flexible')
for kind,steps in [('rollouts',[1,20,40,60]),('val_generations',[0,20,40,60])]:
    print('==',kind)
    for st in steps:
        rows=[json.loads(l) for l in open(f'results/run60/{kind}/{st}.jsonl')]
        n=len(rows); g=0; r=0; d=0; missing=0
        for x in rows:
            ln=lastnum_grader(x['output']); gt=x['gts']
            try: ok=float(ln)==float(gt)
            except: ok=False
            rv=rew_flex(x['output'],gt)
            g+=ok; r+=rv; d+= (ok != bool(rv))
            if not ok and gt in [z.replace(',','') for z in re.findall(r'-?\d[\d,]*\.?\d*', x['output'])]: missing+=1
        print(st,'n',n,'grader',round(g/n,4),'reward',round(r/n,4),'disagree',d,'gold_present_but_wrong',missing)
EOF

