cd /workspace/results/run60/rollouts && python3 - <<'EOF'
import json, re, glob

# grader rule: last number in the whole response, numeric equality
NUM = re.compile(r'-?\d[\d,]*(?:\.\d+)?')

def last_number(s):
    m = NUM.findall(s)
    if not m: return None
    return m[-1].replace(',', '')

def to_float(x):
    try: return float(x)
    except: return None

for f in ['1.jsonl','10.jsonl','20.jsonl','30.jsonl','40.jsonl','50.jsonl','60.jsonl']:
    rows=[json.loads(l) for l in open(f)]
    agree=0; mism=[]; noans=0
    for r in rows:
        g = to_float(r['gts'])
        ln = last_number(r['output'])
        v = to_float(ln) if ln is not None else None
        corr = (v is not None and g is not None and abs(v-g) < 1e-9)
        if ln is None: noans += 1
        if corr == (r['score'] == 1.0):
            agree += 1
        else:
            mism.append((r['score'], ln, r['gts'], r['output'][-160:]))
    print(f, 'n=%d grader=%.4f reward=%.4f disagree=%d no_number=%d' % (
        len(rows), sum(1 for r in rows if (lambda g,v: v is not None and g is not None and abs(v-g)<1e-9)(to_float(r['gts']), to_float(last_number(r['output']) or 'x')))/len(rows),
        sum(r['score'] for r in rows)/len(rows), len(mism), noans))
    for m in mism[:3]:
        print('   reward=%s lastnum=%r gold=%r tail=%r' % (m[0], m[1], m[2], m[3][-100:]))
EOF

